export const commandReference=[
['np · naprzod · naprzód','fd · forward','np 80','Ruch do przodu.'],['ws · wstecz','bk · back','ws 40','Ruch do tyłu.'],['pw · prawo','rt · right','pw 90','Skręt w prawo wokół własnej osi góry.'],['lw · lewo','lt · left','lw 45','Skręt w lewo.'],['pod · podnies · podnieś','pu · penup','pod np 30','Podnieś pisak: ruch bez rysowania.'],['opu · opusc · opuść','pd · pendown','opu np 30','Opuść pisak.'],['kolor','color','kolor \"#16866a\"','Kolor jako sześć cyfr szesnastkowych w cudzysłowie.'],['grubosc · grubość','width','grubosc 3','Całkowita grubość od 1 do 12 pikseli.'],['powtorz · powtórz','repeat','powtorz 4 [np 80 pw 90]','Całkowita liczba powtórzeń od 0 do 10 000. W ciele nrpowt (repcount) podaje numer iteracji od 1.'],['niech','let','niech bok 80','Przypisz lub zmień zmienną.'],['jeśli · jesli','if','jeśli bok > 20 [np bok]','Wykonaj ciało, jeśli porównanie jest prawdziwe.'],['jeżeli · jezeli','ifelse','jeżeli bok = 80 [pw 90] [lw 90]','Pierwsze ciało dla prawdy, drugie dla fałszu.'],['stop','stop','jeśli bok < 5 [stop]','Zakończ bieżącą procedurę lub cały program na poziomie głównym.'],['dom','home','dom','Wróć do (0, 0, 0) i początkowej orientacji, rysując, gdy pisak jest opuszczony.'],['czyść · czysc','cs · clearscreen','czyść','Usuń odcinki bez zmiany pozycji, orientacji i pisaka.'],['gora · góra','pitchup','gora 90 np 50','Tylko 3D: obróć nos ku własnej górze.'],['dol · dół','pitchdown','dol 45','Tylko 3D: obróć nos w dół.'],['pp · przechylprawo','rr · rollright','pp 90','Tylko 3D: obróć górę ku prawej stronie, wokół kierunku ruchu.'],['pl · przechyllewo','rl · rollleft','pl 30','Tylko 3D: przechył w lewo.'],['oto … ma: … / już','to / juz · end','oto kwadrat ma: bok\\n  powtorz 4 [np bok pw 90]\\njuż\\nkwadrat 80','Zdefiniuj procedurę. Starsza forma nagłówka: oto kwadrat :bok.']
];
export function referenceHTML(){return "'`<div class="reference-intro"><span class="eyebrow">PODRĘCZNIK ŻÓŁWIA</span><h2>Mały język. Nieskończone możliwości.</h2><p>Żółw zaczyna w punkcie (0, 0, 0), patrząc w kierunku +Y. Jego prawa strona to +X, a góra to +Z. Pisak jest opuszczony, zielony (#16866a), o grubości 3.</p></div><h3>Wszystkie polecenia</h3><p>Wielkość liter nie ma znaczenia. Polskie i angielskie nazwy są równoważne. Kąty podajemy w stopniach, odległości w jednostkach płótna. Liczby ujemne odwracają ruch lub obrót.</p><div class="ref-table">${commandReference.map(([pl,en,ex,desc])=>`<article><div><strong>${pl}</strong><small>${en}</small></div><p>${desc}</p><pre>${escapeHTML(ex)}</pre></article>`).join('"'')}</div><h3>Wyrażenia i liczby</h3><p>Liczby dziesiętne: 80, 12.5, .5. Zapis naukowy (1e3), szesnastkowy, NaN i Infinity są błędami. Dostępne są +, −, *, / oraz nawiasy. Mnożenie i dzielenie mają pierwszeństwo. Pozostałe działania wykonują się od lewej: <code>np 20 - 5 - 3</code> przesuwa o 12, <code>np 2 + 3 * 4</code> o 14.</p><pre>np -(3 - 5)\\nnp - -2\\nniech bok 80\\nnp bok / 2</pre><p>Operator binarny ma spacje po obu stronach albo po żadnej: <code>10 - 5</code> i <code>10-5</code> są poprawne. <code>np 10 -5</code> jest błędem. Znaki jednoargumentowe można łączyć i stosować do nazw. Dzielenie przez zero i nieskończony wynik zatrzymują program.</p><h3>Zmienne i warunki</h3><p>Nazwy zaczynają się literą, dalej mogą mieć litery, cyfry i podkreślenia. Nie używaj nazw poleceń ani procedur dla zmiennych. Nazwy i parametry ignorują wielkość liter. Zmienna musi być zadeklarowana przez niech w odpowiednim zakresie, ale odczyt przed przypisaniem na wykonywanej ścieżce jest błędem. Na poziomie głównym zmienne są globalne. W procedurze przypisanie tworzy lokalną zmienną, przesłaniając globalną; parametr też można zmienić. Parametr może mieć taką samą nazwę jak procedura. Zapis <code>:bok</code> oznacza to samo co <code>bok</code>.</p><pre>niech bok 40\\njeżeli bok >= 40 [np bok] [np 20]</pre><p>Porównania: &lt;, &gt;, =, &lt;=, &gt;=, &lt;&gt;. Są dokładne: 0.1 + 0.2 nie jest równe 0.3. Ciała warunków i powtórzeń mogą się zagnieżdżać. Średnik rozpoczyna komentarz do końca wiersza.</p><h3>Powtórzenia i procedury</h3><pre>powtorz 10 [np nrpowt * 5 pw 90]\\n\\noto gałąź ma: długość\\n  jeśli długość &lt; 5 [stop]\\n  np długość\\n  gałąź długość * 0.7\\njuż\\ngałąź 40</pre><p>nrpowt odczytuje najbliższe powtórzenie w tekście programu, od 1. Nie może wystąpić poza nim, nawet w procedurze wołanej z powtórzenia. Procedury mogą wywoływać siebie i inne procedury. Definicje są tylko na poziomie głównym, mogą znajdować się przed lub po wywołaniu. Nagłówek oto musi zaczynać wiersz; parametry po ma: oddzielaj przecinkami. już musi być samo w swoim wierszu. Każdą nazwę procedury definiujemy raz. Argumentów jest dokładnie tyle, ile parametrów; każdy argument jest wyrażeniem. Procedury nie zwracają wartości.</p><h3>Geometria i pisak</h3><p>Obroty są lokalne względem żółwia, także po przechyleniu. Po gora 90 kierunek to poprzednia góra. Po pp 90 góra to poprzednia prawa strona, a prawa strona to poprzedni dół. Polecenia płaskie dają identyczne współrzędne w 2D i 3D. Ruch o zero nie rysuje. dom przywraca pozycję i orientację, zachowując pisak, kolor i grubość; czyść usuwa tylko odcinki.</p><h3>Błędy i limity</h3><p>Cały program jest sprawdzany przed rysowaniem. Błąd składni nie rysuje niczego, a błąd wykonania zachowuje istniejące odcinki (po ostatnim czyść). Błędne argumenty wskazują początek wyrażenia. Stałe grubości i liczby powtórzeń są sprawdzane przed wykonaniem; zależne od nazw — w trakcie.</p><ul><li>50 000 znaków i 10 000 tokenów (również operatory, nawiasy i przecinki).</li><li>32 poziomy nawiasów kwadratowych.</li><li>32 aktywne wywołania procedur i powtórzenia razem; warunki nie zajmują ramki.</li><li>10 000 operacji: każde polecenie, przypisanie, warunek, powtórzenie i wywołanie oraz zakończenie każdej iteracji, ciała warunku i wywołania. Wyrażenia nie liczą się jako operacje.</li><li>10 000 zachowanych odcinków. Każda współrzędna w zakresie ±100 000.</li></ul><h3>Skróty klawiaturowe</h3><p>Ctrl / ⌘ + Enter: uruchom. Alt + →: krok. Alt + Spacja: pauza / wznów. Alt + R: reset. Na płótnie: strzałki przesuwają widok (w 3D obracają kamerę), Shift + strzałki przesuwają kamerę, + / − powiększają, 0 dopasowuje rysunek. Tab przechodzi do kolejnych kontrolek.</p>"'`}
export function escapeHTML(s){return s.replaceAll('"'&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('\"','&quot;')}
